def min_paint_to_achieve_beauty(n, m, k, colors, paint_costs):
    from functools import lru_cache

    # Helper function to calculate beauty of a given coloring
    def calculate_beauty(coloring):
        beauty = 1
        for i in range(1, n):
            if coloring[i] != coloring[i - 1]:
                beauty += 1
        return beauty

    # Recursive function with memoization to find the minimum paint
    @lru_cache(None)
    def dfs(index, current_beauty, current_coloring):
        if index == n:
            return 0 if current_beauty == k else float('inf')

        if current_beauty > k:
            return float('inf')

        min_paint = float('inf')

        # If the tree is already colored
        if colors[index] != 0:
            new_coloring = current_coloring[:index] + (colors[index],) + current_coloring[index + 1:]
            min_paint = dfs(index + 1, calculate_beauty(new_coloring), new_coloring)
        else:
            # Try coloring the tree with each color
            for color in range(1, m + 1):
                new_coloring = current_coloring[:index] + (color,) + current_coloring[index + 1:]
                paint_used = paint_costs[index][color - 1]
                min_paint = min(min_paint, paint_used + dfs(index + 1, calculate_beauty(new_coloring), new_coloring))

        return min_paint

    # Initial coloring is the same as the given colors
    initial_coloring = tuple(colors)
    result = dfs(0, 1, initial_coloring)

    return result if result != float('inf') else -1

